// 1) In ComfyUI open your text-to-video workflow and use Workflow > Export (API).
// 2) In that JSON, set the positive prompt text to exactly: __SCENE_PROMPT__
// 3) Paste the whole exported JSON between the braces below (replace the {}).
const COMFY_WORKFLOW = {};

if (!COMFY_WORKFLOW || Object.keys(COMFY_WORKFLOW).length === 0) {
  throw new Error('ComfyUI workflow not configured. Open the "Build ComfyUI Job" node and paste your Export (API) JSON into COMFY_WORKFLOW.');
}

const pkg = $('Parse Video Package').first().json;
const scenes = Array.isArray(pkg.scenes) ? pkg.scenes : [];
const vertical = String(pkg.format || '').toLowerCase().includes('short');
const scenePrompt = (scenes.map(s => s.visual_prompt).filter(Boolean).join('. ') || pkg.title || 'cinematic video')
  + (vertical ? '. Vertical 9:16 composition.' : '. Widescreen 16:9 composition.');

const graph = JSON.parse(JSON.stringify(COMFY_WORKFLOW));
let replaced = 0;
for (const nodeId of Object.keys(graph)) {
  const inputs = (graph[nodeId] && graph[nodeId].inputs) || {};
  for (const key of Object.keys(inputs)) {
    if (typeof inputs[key] === 'string' && inputs[key].includes('__SCENE_PROMPT__')) {
      inputs[key] = inputs[key].split('__SCENE_PROMPT__').join(scenePrompt);
      replaced++;
    }
    if ((key === 'seed' || key === 'noise_seed') && typeof inputs[key] === 'number') {
      inputs[key] = Math.floor(Math.random() * 1e15);
    }
  }
}
if (replaced === 0) {
  throw new Error('No __SCENE_PROMPT__ marker found in COMFY_WORKFLOW. Put __SCENE_PROMPT__ as the positive prompt text in your exported JSON.');
}

return [{ json: { body: { prompt: graph }, scenePrompt } }];

const j = $input.first().json;
const raw = j.status || (j.execution_status && j.execution_status.status_str) || (j.status && j.status.status_str) || '';
const status = String(raw).toLowerCase();
const terminalFail = ['error', 'non_retryable_error', 'lost', 'cancelled', 'failed'];
const attempts = $runIndex + 1;

let video = null;
const outputs = j.outputs || {};
for (const nodeId of Object.keys(outputs)) {
  const out = outputs[nodeId] || {};
  for (const key of ['videos', 'gifs', 'images', 'files']) {
    for (const f of (Array.isArray(out[key]) ? out[key] : [])) {
      if (!video && f && f.filename && /\.(mp4|webm|mov)$/i.test(f.filename)) video = f;
    }
  }
}

let state = 'running';
if (status === 'success' || status === 'completed') state = video ? 'done' : 'failed';
else if (terminalFail.includes(status)) state = 'failed';
else if (attempts >= 40) state = 'failed';

const reason = state === 'failed'
  ? (status === 'success' || status === 'completed' ? 'Job finished but no MP4/WebM output was found. Make sure your ComfyUI workflow ends with a Save Video node.'
    : attempts >= 40 && !terminalFail.includes(status) ? 'Timed out after ~20 minutes waiting for Comfy Cloud.'
    : 'Comfy Cloud job ended with status: ' + status)
  : '';

return [{ json: { state, status, attempts, reason, filename: video ? video.filename : '', subfolder: video ? (video.subfolder || '') : '', type: video ? (video.type || 'output') : 'output' } }];

