const raw = String($input.first().json.output ?? '');
let parsed;
try {
  const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = {
    reply: 'I could not safely process the interview response. Please try again or rephrase your last answer.',
    readyToGenerate: false,
    cv: {}
  };
}
if (!parsed || typeof parsed !== 'object') parsed = {};
return [{json: {
  reply: String(parsed.reply ?? 'Please continue with your CV interview.'),
  readyToGenerate: parsed.readyToGenerate === true,
  cv: parsed.cv && typeof parsed.cv === 'object' ? parsed.cv : {}
}}];

const cv = $('Parse Agent JSON').first().json.cv || {};
const safe = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const list = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const lines = (v) => list(v).filter(Boolean).map(x => `<li>${safe(x)}</li>`).join('');
const section = (title, body) => body ? `<section><h2>${safe(title)}</h2>${body}</section>` : '';
const experience = list(cv.experience).map(e => `<article><h3>${safe(e.title)}${e.employer ? ' | ' + safe(e.employer) : ''}</h3><p class="meta">${safe(e.location)}${e.dates ? ' | ' + safe(e.dates) : ''}</p>${list(e.description).length ? `<ul>${lines(e.description)}</ul>` : ''}${list(e.achievements).length ? `<ul>${lines(e.achievements)}</ul>` : ''}</article>`).join('');
const education = list(cv.education).map(e => `<article><h3>${safe(e.qualification)}</h3><p>${safe(e.institution)}${e.location ? ' | ' + safe(e.location) : ''}${e.dates ? ' | ' + safe(e.dates) : ''}</p>${list(e.details).length ? `<ul>${lines(e.details)}</ul>` : ''}</article>`).join('');
const certifications = list(cv.certifications).map(e => `<li>${safe(e.name)}${e.issuer ? ' | ' + safe(e.issuer) : ''}${e.date ? ' | ' + safe(e.date) : ''}</li>`).join('');
const projects = list(cv.projects).map(e => `<article><h3>${safe(e.name)}</h3><p>${safe(e.description)}</p>${e.url ? `<p>${safe(e.url)}</p>` : ''}</article>`).join('');
const languages = list(cv.languages).map(e => typeof e === 'string' ? safe(e) : `${safe(e.name)}${e.level ? ' - ' + safe(e.level) : ''}`).join(' · ');
const contact = [cv.email, cv.phone, cv.location, cv.linkedin, cv.website].filter(Boolean).map(safe).join(' | ');
const styles = {
  'Modern Professional': 'body{font-family:Arial,sans-serif;color:#263447}header{background:#183b56;color:white;padding:28px}header h1{margin:0;font-size:30px}header p{margin:7px 0}h2{color:#087e8b;border-bottom:2px solid #d5e8ea;padding-bottom:5px;text-transform:uppercase;font-size:15px}h3{margin-bottom:4px}section{margin:20px 0}.meta{color:#536579;font-size:12px}',
  'ATS Friendly': 'body{font-family:Arial,sans-serif;color:#111}header{padding:8px 0;border-bottom:2px solid #222}header h1{margin:0;font-size:26px}h2{font-size:15px;border-bottom:1px solid #333;text-transform:uppercase;margin-top:18px}h3{font-size:13px;margin-bottom:3px}section{margin:12px 0}.meta{font-size:12px}',
  'Executive': 'body{font-family:Georgia,serif;color:#202b39}header{border-bottom:4px solid #a78245;padding:22px 0}header h1{font-size:32px;margin:0}header p{color:#7c612f}h2{font-size:14px;letter-spacing:1px;color:#7c612f;border-bottom:1px solid #cbb98f;padding-bottom:5px}h3{margin-bottom:4px}section{margin:22px 0}.meta{font-size:12px;color:#666}',
  'Minimalist': 'body{font-family:Arial,sans-serif;color:#333;line-height:1.6}header{padding:15px 0}header h1{font-size:29px;font-weight:500;margin:0}h2{font-size:13px;letter-spacing:1.5px;color:#666;margin-top:25px}h3{font-size:14px;margin-bottom:2px}section{margin:18px 0}.meta{font-size:12px;color:#777}'
};
const templates = Object.keys(styles);
const summary = cv.summary ? section('Professional Summary', `<p>${safe(cv.summary)}</p>`) : '';
const skills = list(cv.skills).length ? section('Skills', `<ul>${lines(cv.skills)}</ul>`) : '';
const content = `${summary}${section('Work Experience', experience)}${section('Education', education)}${skills}${section('Certifications', certifications ? `<ul>${certifications}</ul>` : '')}${section('Projects', projects)}${section('Languages', languages ? `<p>${languages}</p>` : '')}`;
const files = [];
for (const template of templates) {
  const css = styles[template] + ' @page{size:A4;margin:16mm} body{max-width:850px;margin:0 auto;padding:26px}p{margin:5px 0}ul{padding-left:20px}li{margin:3px 0}article{margin:12px 0}@media print{body{max-width:none;padding:0}section,article{break-inside:avoid}header{print-color-adjust:exact;-webkit-print-color-adjust:exact}}';
  const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${safe(cv.fullName || 'CV')} - ${safe(template)}</title><style>${css}</style></head><body><header><h1>${safe(cv.fullName || '[Full Name]')}</h1><p>${safe(cv.headline || cv.targetRole || '')}</p><p>${contact || '[Contact details]'}</p></header>${content}<footer><p>Template: ${safe(template)}</p></footer></body></html>`;
  const slug = template.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const fileName = `${slug}.pdf`;
  files.push({json: {template, fileName}, binary: {data: {data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html'}}});
}
return files;

