  manifestText = Buffer.from(rawManifest.replace(/\s/g, ''), 'base64').toString('utf8');
} catch (error) {
  throw new Error('Unable to decode the GitHub manifest. No backup was committed.');
}

let previousManifest;
try {
  previousManifest = JSON.parse(manifestText);
} catch (error) {
  throw new Error('The GitHub manifest is not valid JSON. Repair state/manifest.json before running.');
}

if (!Array.isArray(previousManifest.currentWorkflows)) {
  throw new Error('The manifest must contain a currentWorkflows array.');
}

const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '-');
const secretKey = /(password|passwd|secret|token|api.?key|authorization|client.?secret|private.?key)/i;

function redact(value, key = '') {
  if (secretKey.test(key)) return '[REDACTED]';
  if (Array.isArray(value)) return value.map(item => redact(item));
  if (value && typeof value === 'object') {
    const result = {};
    for (const [childKey, childValue] of Object.entries(value)) {
      result[childKey] = redact(childValue, childKey);
    }
    return result;
  }
  return value;
}

const workflows = input.data;
for (const workflow of workflows) {
  if (!workflow.id || !Array.isArray(workflow.nodes) || !workflow.connections) {
    throw new Error('The workflow list appears incomplete or does not include full workflow definitions. No backup was committed. Use the individual workflow endpoint to export complete definitions.');
  }
}

const current = workflows.map(workflow => ({
  id: String(workflow.id),
  name: workflow.name || 'Unnamed workflow',
  updatedAt: workflow.updatedAt || null
}));

const currentIds = new Set(current.map(workflow => workflow.id));
const previousIds = new Set(previousManifest.currentWorkflows.map(workflow => String(workflow.id)));
const previousById = new Map(previousManifest.currentWorkflows.map(workflow => [String(workflow.id), workflow]));
const deleted = previousManifest.currentWorkflows
  .filter(workflow => !currentIds.has(String(workflow.id)))
  .map(workflow => ({
    id: String(workflow.id),
    name: workflow.name || 'Unnamed workflow',
    detectedDeletedAt: now.toISOString(),
    lastKnownUpdatedAt: workflow.updatedAt || null
  }));

const snapshot = {
  backupTimestamp: now.toISOString(),
  source: 'n8n API',
  workflowCount: workflows.length,
  workflows: workflows.map(workflow => redact(workflow))
};

const deletionLog = {
  detectedAt: now.toISOString(),
  deletedCount: deleted.length,
  deletedWorkflows: deleted
};

const deletedHistory = Array.isArray(previousManifest.deletedWorkflows)
  ? previousManifest.deletedWorkflows.concat(deleted)
  : deleted;

const nextManifest = {
  currentWorkflows: current,
  deletedWorkflows: deletedHistory,
  lastSuccessfulBackup: now.toISOString(),
  lastWorkflowCount: workflows.length
};

return [{ json: {
  timestamp,
  snapshotPath: `backups/snapshot-${timestamp}.json`,
  deletionPath: `deletions/deletions-${timestamp}.json`,
  manifestPath: 'state/manifest.json',
  manifestSha: input.sha,
  snapshotBase64: Buffer.from(JSON.stringify(snapshot, null, 2), 'utf8').toString('base64'),
  deletionBase64: Buffer.from(JSON.stringify(deletionLog, null, 2), 'utf8').toString('base64'),
  manifestBase64: Buffer.from(JSON.stringify(nextManifest, null, 2), 'utf8').toString('base64'),
  workflowCount: workflows.length,
  deletedCount: deleted.length
}}];

